mapper.select:
SELECT * FROM TBL_BILL_DISCOUNT
WHERE DELETE_FLAG = 0

    AND DISCOUNT_NUMBER LIKE CONCAT('%', #{query.discountNumber}, '%')


    AND BILL_NUMBER LIKE CONCAT('%', #{query.billNumber}, '%')


    AND DISCOUNT_TYPE = #{query.discountType}


    AND DISCOUNT_BANK LIKE CONCAT('%', #{query.discountBank}, '%')


    AND DISCOUNT_STATUS = #{query.discountStatus}


    AND APPLICATION_DATE >= #{query.applicationDateStart}


    AND APPLICATION_DATE <= #{query.applicationDateEnd}


    AND BILL_AMOUNT >= #{query.amountMin}


    AND BILL_AMOUNT <= #{query.amountMax}


    AND COMPANY_ID = #{query.companyId}


    AND DEPT_ID = #{query.deptId}

ORDER BY CREATE_TIME DESC

