SELECT INSTRUMENT_ID AS "billId", INSTRUMENT_NO AS "billNumber", BILL_TYPE AS "billType", BILL_AMOUNT AS "billAmount", CURRENCY_CODE AS "currency", DRAWER AS "drawer", PAYEE AS "payee", ACCEPTOR AS "acceptor", ISSUE_DATE AS "issueDate", MATURITY_DATE AS "maturityDate", BILL_STATUS AS "billStatus", REMARK AS "remark" FROM TBL_BILL_INSTRUMENT WHERE DELETE_FLAG = 0 AND BILL_STATUS IN ('NORMAL', 'ACCEPTED', 'ISSUED', 'HOLDING', '正常', '已承兑', '已开立', '持有中') AND MATURITY_DATE > SYSDATE AND INSTRUMENT_NO NOT IN ( SELECT BILL_NUMBER FROM TBL_BILL_DISCOUNT WHERE DELETE_FLAG = 0 AND DISCOUNT_STATUS IN ('PENDING', 'APPROVED', 'COMPLETED', '申请中', '已审批', '已完成') AND BILL_NUMBER IS NOT NULL )
AND INSTRUMENT_NO LIKE CONCAT('%', #{params.billNumber}, '%')
AND BILL_TYPE = #{params.billType}
AND BILL_AMOUNT >= #{params.amountMin}
AND BILL_AMOUNT <= #{params.amountMax}
ORDER BY MATURITY_DATE ASC, BILL_AMOUNT DESC
